"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["64714"],{25035(e){e.exports=JSON.parse('{"id":"FIN-1308","slug":"bank-resolution","term":"Bank Resolution","also_known_as":[],"difficulty":"Advanced","definition":"Bank resolution is the process by which authorities manage the failure of a bank in an orderly way, protecting critical services, depositors and financial stability while avoiding the use of taxpayers\' money.","explanation":["Before the 2008 financial crisis, governments often had two poor choices when a large bank failed: let it collapse, risking chaos, or bail it out with public money. Resolution frameworks introduced since then provide a third option.","Resolution authorities have powers to take control of a failing bank and restructure it. Tools include selling all or part of the bank to another institution, transferring good assets to a temporary bridge bank, separating bad assets into an asset management vehicle, and bail-in, which imposes losses on shareholders and creditors and converts some debts into equity.","For example, when the Spanish bank Banco Popular failed in 2017, European authorities wrote down its shares and some debt, and sold it to Santander for a nominal sum of one euro, with no cost to taxpayers.","Large banks must prepare resolution plans, sometimes called living wills, showing how they could be resolved. They must also hold sufficient loss-absorbing capital and debt that can be bailed in."],"note":"","total":1500,"prev":{"slug":"bank-reconciliation","term":"Bank Reconciliation"},"next":{"slug":"bank-run","term":"Bank Run"}}')}}]);